uniform float u_value2; // Speed
uniform float u_value3; // Amplitude
uniform float u_value4; // Frequency
uniform float u_value5; // Direction Mix
uniform float u_value6; // Brightness

void main()
{
    vec2 uv = vTexCoord;

    float t =
        u_value1 *
        (0.5 + u_value2 * 5.0);

    // ==========================
    // RIGHT -> LEFT WAVE
    // ==========================

    float wave =
        sin(
            uv.x *
            (5.0 + u_value4 * 30.0)
            + t
        );

    uv.y +=
        wave *
        0.05 *
        u_value3;

    // ==========================
    // OPTIONAL HORIZONTAL WAVE
    // ==========================

    uv.x +=
        wave *
        0.02 *
        u_value5;

    vec4 color =
        texture2D(
            u_texture,
            uv
        );

    color.rgb *=
        0.5 +
        u_value6 * 1.5;

    gl_FragColor = color;
}

