precision mediump float;
precision mediump int;
precision lowp sampler2D;

varying vec2 vTexCoord;
uniform sampler2D u_texture;

uniform float u_value1; // Time
uniform float u_value2; // Speed
uniform float u_value3; // Amount
uniform float u_value4; // Randomness
uniform float u_value5; // Smoothness
uniform float u_value6; // Brightness

float rand(float n)
{
    return fract(sin(n) * 43758.5453123);
}

mat2 rotate(float a)
{
    float s = sin(a);
    float c = cos(a);
    return mat2(c, -s, s, c);
}

void main()
{
    vec2 uv = vTexCoord;

    float t =
        u_value1 *
        (1.0 + u_value2 * 20.0);

    float stepTime =
        floor(
            t *
            (1.0 + u_value5 * 20.0)
        );

    // Shake
    float shake =
        (rand(stepTime) - 0.5)
        * 0.1
        * u_value3;

    shake +=
        sin(t * 10.0)
        * 0.02
        * u_value4;

    uv.y += shake;

    // Random Rotation
    float rot =
        (rand(stepTime + 13.7) - 0.5)
        * 0.3
        * u_value3;

    rot +=
        sin(t * 4.0)
        * 0.05
        * u_value4;

    uv -= 0.5;
    uv = rotate(rot) * uv;
    uv += 0.5;

    vec4 color =
        texture2D(
            u_texture,
            uv
        );

    color.rgb *=
        0.5 +
        u_value6 * 1.5;

    gl_FragColor = color;
}

