precision mediump float;
precision mediump int;
precision lowp sampler2D;

varying vec2 vTexCoord;
uniform sampler2D u_texture;

uniform float u_value1; // Edge Width
uniform float u_value2; // Glow Strength
uniform float u_value3; // Red
uniform float u_value4; // Green
uniform float u_value5; // Blue
uniform float u_value6; // Brightness

void main()
{
    vec2 uv = vTexCoord;

    vec4 base =
        texture2D(
            u_texture,
            uv
        );

    float w =
        0.001 +
        u_value1 * 0.02;

    vec4 c1 =
        texture2D(
            u_texture,
            uv + vec2(w,0.0)
        );

    vec4 c2 =
        texture2D(
            u_texture,
            uv - vec2(w,0.0)
        );

    vec4 c3 =
        texture2D(
            u_texture,
            uv + vec2(0.0,w)
        );

    vec4 c4 =
        texture2D(
            u_texture,
            uv - vec2(0.0,w)
        );

    float edge =
        length(c1.rgb - c2.rgb) +
        length(c3.rgb - c4.rgb);

    vec3 glowColor =
        vec3(
            u_value3,
            u_value4,
            u_value5
        );

    vec3 col =
        base.rgb;

    col +=
        glowColor *
        edge *
        u_value2 *
        3.0;

    col *=
        0.5 +
        u_value6 * 1.5;

    gl_FragColor =
        vec4(col, base.a);
}

