precision mediump float;
precision mediump int;
precision lowp sampler2D;

varying vec2 vTexCoord;
uniform sampler2D u_texture;

uniform float u_value1; // Time
uniform float u_value2; // Speed
uniform float u_value3; // Expansion
uniform float u_value4; // Glass
uniform float u_value5; // Density
uniform float u_value6; // Brightness

float hash(float n)
{
    return fract(sin(n) * 43758.5453123);
}

void main()
{
    vec2 uv = vTexCoord;

    float t =
        u_value1 *
        (0.2 + u_value2 * 2.0);

    float warp = 0.0;

    // Layer 1
    float p1 =
        0.2 +
        0.15 *
        sin(t * 0.7);

    warp +=
        exp(
            -abs(uv.x - p1) *
            (10.0 + u_value5 * 20.0)
        );

    // Layer 2
    float p2 =
        0.5 +
        0.25 *
        cos(t * 0.5);

    warp +=
        exp(
            -abs(uv.x - p2) *
            (8.0 + u_value5 * 15.0)
        );

    // Layer 3
    float p3 =
        0.8 +
        0.12 *
        sin(t * 0.9);

    warp +=
        exp(
            -abs(uv.x - p3) *
            (12.0 + u_value5 * 25.0)
        );

    warp *=
        u_value3;

    // Glass distortion
    uv.x +=
        sin(
            uv.y * 20.0 +
            t
        ) *
        0.01 *
        u_value4 *
        warp;

    uv.y +=
        cos(
            uv.x * 15.0 +
            t
        ) *
        0.008 *
        u_value4 *
        warp;

    // Expansion
    uv.x =
        0.5 +
        (uv.x - 0.5)
        *
        (1.0 - warp * 0.15);

    vec4 color =
        texture2D(
            u_texture,
            uv
        );

    // Highlight
    color.rgb +=
        warp *
        0.15;

    color.rgb *=
        0.5 +
        u_value6 * 1.5;

    gl_FragColor = color;
}

