precision mediump float;
precision mediump int;
precision lowp sampler2D;

varying vec2 vTexCoord;
uniform sampler2D u_texture;

uniform float u_value1; // Time
uniform float u_value2; // Speed
uniform float u_value3; // Scale
uniform float u_value4; // Distortion
uniform float u_value5; // Glow
uniform float u_value6; // Brightness

void main()
{
    vec2 uv = vTexCoord * 2.0 - 1.0;

    float t =
        u_value1 *
        (0.2 + u_value2 * 2.0);

    float x = uv.x;
    float y = uv.y;

    x += sin(y * 8.0 + t) * 0.2 * u_value4;
    y += cos(x * 8.0 - t) * 0.2 * u_value4;

    x += sin(y * 16.0 + t * 1.3) * 0.08;
    y += cos(x * 16.0 - t * 1.1) * 0.08;

    float lines =
        sin(x * (40.0 + u_value3 * 120.0));

    lines = abs(lines);

    lines = pow(
        1.0 - lines,
        6.0
    );

    vec3 col =
        vec3(lines);

    col +=
        lines *
        u_value5;

    col *=
        (0.5 + u_value6 * 1.5);

    gl_FragColor =
        vec4(col, 1.0);
}

