precision mediump float;
precision mediump int;
precision lowp sampler2D;

varying vec2 vTexCoord;
uniform sampler2D u_texture;

uniform float u_value1; // Time
uniform float u_value2; // Speed
uniform float u_value3; // Density
uniform float u_value4; // Distortion
uniform float u_value5; // Width
uniform float u_value6; // Brightness

void main()
{
    vec2 uv = vTexCoord;

    float t =
        u_value1 *
        (0.2 + u_value2 * 3.0);

    float density =
        10.0 +
        u_value3 * 90.0;

    float cell =
        floor(uv.x * density);

    float center =
        (cell + 0.5) / density;

    float local =
        (uv.x - center) * density;

    float bend =
        sin(
            cell * 1.7 +
            t
        );

    bend *=
        (1.0 - abs(local));

    uv.x +=
        bend *
        0.05 *
        u_value4;

    uv.x +=
        local *
        local *
        0.02 *
        u_value5;

    vec4 color =
        texture2D(
            u_texture,
            uv
        );

    color.rgb *=
        0.5 +
        u_value6 * 1.5;

    gl_FragColor = color;
}

