shaderFragment.v:
#version 300 es
precision highp float;

in vec2 vTexCoord;
in vec4 vColor;

uniform float u_value1;
uniform float u_value2;
uniform float u_value3;
uniform float u_value4;
uniform float u_value5;
uniform float u_value6;

out vec4 fragColor;

vec2 hash(vec2 p, float seed) {
    p = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)));
    p += floor(seed * 1000.0);
    return -1.0 + 2.0 * fract(sin(p) * 43758.5453123);
}

float noise(vec2 p, float seed) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(mix(dot(hash(i + vec2(0.0, 0.0), seed), f - vec2(0.0, 0.0)),
                   dot(hash(i + vec2(1.0, 0.0), seed), f - vec2(1.0, 0.0)), u.x),
               mix(dot(hash(i + vec2(0.0, 1.0), seed), f - vec2(0.0, 1.0)),
                   dot(hash(i + vec2(1.0, 1.0), seed), f - vec2(1.0, 1.0)), u.x), u.y);
}

vec3 getRainbow(float t) {
    vec3 c = 0.5 + 0.5 * cos(6.28318 * (t + vec3(0.0, 0.33, 0.67)));
    return c;
}

void main() {
    vec2 uv = vTexCoord;

    float phase = u_value1 * 15.0;
    float scale = 1.0 + u_value2 * 20.0;
    float seed = u_value6; 

    vec2 w1 = vec2(noise(uv * scale + phase, seed), noise(uv * scale - phase, seed));
    vec2 w2 = vec2(noise(uv * scale + w1 + phase * 0.5, seed + 1.5), 
                   noise(uv * scale - w1 - phase * 0.5, seed + 2.5));

    float n = noise(uv * scale + w2, seed);
    float dist = abs(fract(n * 3.0 + phase) - 0.5);

    vec3 coreColor = getRainbow(u_value5);
    vec3 glowColor = getRainbow(u_value5 + 0.05) * 0.6;

    float safeGlow = 0.05 + u_value4 * 0.95;
    float thickness = 0.002 + u_value3 * 0.1;

    float line = smoothstep(thickness, 0.0, dist);

    float glowPower = 1.0 / (0.01 + pow(safeGlow, 2.0) * 0.5);
    float glow = exp(-dist * glowPower * 10.0);

    vec3 finalColor = glowColor * glow * (safeGlow * 5.0);
    finalColor += coreColor * line;

    finalColor *= (n * 0.4 + 0.8);

    fragColor = vec4(finalColor, 1.0) * vColor;
}

