precision mediump float;
precision mediump int;
precision lowp sampler2D;

varying vec2 vTexCoord;
uniform sampler2D u_texture;

uniform float u_value1; // Time
uniform float u_value2; // Rotation Speed
uniform float u_value3; // Gravity
uniform float u_value4; // Ring Density
uniform float u_value5; // Glow
uniform float u_value6; // Warp

void main()
{
    vec2 uv = vTexCoord;

    vec2 center = vec2(0.5);

    vec2 p = uv - center;

    float dist = length(p);

    float angle = atan(p.y,p.x);

    float t =
        u_value1 *
        (1.0 + u_value2 * 8.0);

    // ======================
    // EVENT HORIZON
    // ======================

    float gravity =
        (1.0 - dist);

    gravity *= gravity;

    // ======================
    // SPACE WARP
    // ======================

    angle +=
        gravity *
        (3.0 + u_value3 * 12.0);

    // ======================
    // PHOTON RINGS
    // ======================

    float ring1 =
        sin(
            dist *
            (40.0 + u_value4 * 80.0)
            - t * 3.0
        );

    float ring2 =
        sin(
            dist *
            (18.0 + u_value4 * 30.0)
            + t * 2.0
        );

    float ring3 =
        cos(
            dist *
            (60.0 + u_value4 * 120.0)
            - t * 5.0
        );

    float rings =
        ring1 * 0.5 +
        ring2 * 0.3 +
        ring3 * 0.2;

    // ======================
    // ACCRETION DISK
    // ======================

    angle +=
        rings *
        0.25 *
        (0.2 + u_value6);

    dist +=
        rings *
        0.025 *
        (0.2 + u_value6);

    // ======================
    // WAVE DISTORTION
    // ======================

    dist +=
        sin(
            angle * 8.0
            - t * 2.0
        )
        * 0.015
        * u_value6;

    // ======================
    // REBUILD UV
    // ======================

    vec2 finalUV =
        center +
        vec2(
            cos(angle),
            sin(angle)
        ) * dist;

    vec4 col =
        texture2D(
            u_texture,
            finalUV
        );

    // ======================
    // CORE GLOW
    // ======================

    float core =
        smoothstep(
            0.35,
            0.0,
            dist
        );

    col.rgb +=
        core *
        (0.5 + u_value5 * 3.0);

    // ======================
    // PHOTON RING GLOW
    // ======================

    float photon =
        smoothstep(
            0.04,
            0.0,
            abs(dist - 0.18)
        );

    col.rgb +=
        photon *
        (0.3 + u_value5 * 2.0);

    // ======================
    // ENERGY PULSE
    // ======================

    col.rgb *=
        1.0 +
        sin(t * 3.0)
        * 0.08;

    // ======================
    // VIGNETTE
    // ======================

    col.rgb *=
        1.0 -
        dist * 0.4;

    gl_FragColor =
        vec4(col.rgb,1.0);
}

