precision lowp sampler2D;

varying vec2 vTexCoord;
uniform sampler2D u_texture;

uniform float u_value1; // Beat
uniform float u_value2; // Depth
uniform float u_value3; // Width
uniform float u_value4; // Side
uniform float u_value5; // Perspective
uniform float u_value6; // Brightness

void main()
{
    vec2 uv = vTexCoord;

    float beat = u_value1;

    float mask;

    if(u_value4 < 0.5)
    {
        mask =
            1.0 -
            smoothstep(
                0.0,
                u_value3,
                uv.x
            );
    }
    else
    {
        mask =
            smoothstep(
                1.0 - u_value3,
                1.0,
                uv.x
            );
    }

    float depth =
        beat *
        mask *
        u_value2;

    uv.y =
        0.5 +
        (uv.y - 0.5)
        *
        (1.0 - depth * u_value5);

    uv.x +=
        depth *
        0.08;

    vec4 color =
        texture2D(
            u_texture,
            uv
        );

    color.rgb *=
        1.0 +
        depth *
        0.5;

    color.rgb *=
        0.5 +
        u_value6 * 1.5;

    gl_FragColor = color;
}

