    radius *=
        0.9 +
        rnd * 0.2;

    float d =
        length(p);

    // LED BODY

    float led =
        1.0 -
        smoothstep(
            radius,
            radius + 0.03,
            d
        );

    // HOTSPOT

    float core =
        1.0 -
        smoothstep(
            radius * 0.05,
            radius * 0.35,
            d
        );

    // OUTER GLOW

    float glow =
        1.0 -
        smoothstep(
            radius,
            radius + 0.20,
            d
        );

    // BIG BLOOM

    float bloom =
        1.0 -
        smoothstep(
            radius,
            radius + 0.65,
            d
        );

    // DEPTH SHADING

    float depth =
        1.0 -
        d * 1.8;

    depth =
        clamp(
            depth,
            0.0,
            1.0
        );

     // ORGANIC FLICKER

    float flicker =
        0.92 +
        0.08 *
        sin(
            u_value1 * 8.0 +
            rnd * 20.0
        );

    // SCANLINES

    float scan =
        0.96 +
        0.04 *
        sin(
            uv.y * 1200.0
        );

    vec3 grid =
        tex *
        u_value5 *
        0.25;

    vec3 body =
        tex *
        led *
        depth *
        u_value4;

    vec3 hotspot =
        tex *
        core *
        u_value6 *
        2.5;

    vec3 halo =
        tex *
        glow *
        u_value3 *
        1.2;

    vec3 softBloom =
        tex *
        bloom *
        u_value3 *
        0.55;

    vec3 color =
        grid +
        body +
        hotspot +
        halo +
        softBloom;

    color *=
        flicker *
        scan;
 // CONTRAST BOOST

    color =
        pow(
            color,
            vec3(0.90)
        );

    gl_FragColor =
        vec4(
            color,
            1.0
        );
}

