precision mediump float;
precision mediump int;
precision lowp sampler2D;

varying vec2 vTexCoord;
uniform sampler2D u_texture;

uniform float u_value1; // Time
uniform float u_value2; // Speed
uniform float u_value3; // Shake Strength
uniform float u_value4; // Teleport Strength
uniform float u_value5; // Blur
uniform float u_value6; // Brightness

void main()
{
    vec2 uv = vTexCoord;

    float t =
        u_value1 *
        (1.0 + u_value2 * 10.0);

    // ==========================
    // SMOOTH SHAKE
    // ==========================

    float shakeX =
        (
            sin(t * 7.0) +
            sin(t * 13.0) * 0.5 +
            sin(t * 23.0) * 0.25
        )
        * 0.008
        * u_value3;

    float shakeY =
        (
            cos(t * 9.0) +
            cos(t * 17.0) * 0.5 +
            cos(t * 29.0) * 0.25
        )
        * 0.008
        * u_value3;

    // ==========================
    // TELEPORT
    // ==========================

    float jumpTime =
        floor(t * (2.0 + u_value4 * 8.0));

    float jumpX =
        sin(jumpTime * 57.0)
        * 0.04
        * u_value4;

    float jumpY =
        cos(jumpTime * 91.0)
        * 0.04
        * u_value4;

    uv += vec2(
        shakeX + jumpX,
        shakeY + jumpY
    );

    // ==========================
    // MOTION BLUR
    // ==========================

    float blur =
    (u_value5 * 0.004) +
    (abs(jumpX) + abs(jumpY)) * 0.12;

vec4 col = vec4(0.0);

col += texture2D(u_texture, uv) * 4.0;

col += texture2D(u_texture, uv + vec2( blur, 0.0));
col += texture2D(u_texture, uv - vec2( blur, 0.0));

col += texture2D(u_texture, uv + vec2(0.0, blur));
col += texture2D(u_texture, uv - vec2(0.0, blur));

col += texture2D(u_texture, uv + vec2( blur, blur));
col += texture2D(u_texture, uv + vec2(-blur, blur));

col += texture2D(u_texture, uv + vec2( blur,-blur));
col += texture2D(u_texture, uv + vec2(-blur,-blur));

col /= 12.0;

    // ==========================
    // BRIGHTNESS
    // ==========================

    col.rgb *=
        0.5 +
        u_value6 * 1.5;

    gl_FragColor = col;
}

